const order = one(db, 'SELECT on_hold FROM orders WHERE paypal_order_id = ?', orderId)
const already = one(db, 'SELECT 1 AS found FROM shipments WHERE paypal_order_id = ?', orderId)
if (!already && !(order && Number(order.on_hold) === 1)) shipOrder(db, orderId, event.event_type)

const disputedId = disputedCaptureId(event)
const capture = one(db, 'SELECT paypal_order_id FROM captures WHERE paypal_capture_id = ?', disputedId)
let heldOrderId = capture ? String(capture.paypal_order_id) : ''
if (!heldOrderId) {
  try {
    heldOrderId = (await _port.getCapture(disputedId)).orderId
  } catch {
    heldOrderId = ''
  }
}
if (heldOrderId) run(db, 'UPDATE orders SET on_hold = 1 WHERE paypal_order_id = ?', heldOrderId)

export function startReconcile(db: Db, port: PaypalPort): void {
  let busy = false
  const timer = setInterval(async () => {
    if (busy) return
    busy = true
    try {
      const rows = db.prepare('SELECT DISTINCT paypal_order_id FROM captures').all() as Array<{ paypal_order_id: string }>
      for (const row of rows) {
        try {
          const ledger = await port.getOrder(String(row.paypal_order_id))
          for (const refund of ledger.refunds) {
            run(db, 'INSERT OR IGNORE INTO refunds (paypal_refund_id, paypal_order_id, amount) VALUES (?, ?, ?)', refund.id, String(row.paypal_order_id), refund.amount)
          }
        } catch {
          // try again on the next tick
        }
      }
    } finally {
      busy = false
    }
  }, 2000)
  timer.unref()
}
